  ];
  expect(getMagicianState(f.role)).toBeUndefined();
  f.state.history = [
    { day: 2, pair: null },
    { day: 2, pair: [3, 4] },
  ];
  expect(getMagicianState(f.role)).toBeUndefined();
  f.state.history = [{ day: 2, pair: [2, 1] }];
  expect(getMagicianState(f.role)).toBeUndefined();
