import {
  freshNightmareShadowState,
  getNightmareShadowState,
} from "../../../../src/game/mechanisms/roles/nightmare_shadow/state-slot";
// 测试自持当前 Camp，不经旧 Role 属性或隐藏映射提供阵营。
