      electionPolicy: "awa_final_candidates_v1",
      badgePolicy: "awa_next_seat_v1",
      voteWeight: 1.5,
    },
    tieBreaker: { sheriffVote: "min_seat", wolfKillVote: "min_id", exileVote: "min_id" },
